import {rangeBook} from './range-model.js?v=17';
import {statementCovers,fitStatementRange,statementOrder} from './statement-model.js?v=17';
import {MONTHS,figures,total,remaining} from './data.js?v=17';
import {dailyBook,monthDays} from './workbook-model.js?v=17';
import {createPeriodSheet} from './period-ui.js?v=17';

export function createCashbook(a) {
  const {esc,money,date,fullDate,icon,btn,pill,link,panel,empty,stat}=a;
  let selected=a.state.dataset?.defaultDate||'2026-07-18',mode='daily';
  const periodSheet=createPeriodSheet(a,{get selected(){return selected},pick,controls});
  const name=()=>MONTHS[Number(a.month.slice(5))-1]+' de '+a.month.slice(0,4);
  const book=()=>dailyBook(a.state,a.company,a.month,a.account);
  const getDay=()=>{if(selected.slice(0,7)!==a.month)selected=a.month+'-01';return book().find(d=>d.date===selected)||book()[0]};
  const daysOptions=()=>monthDays(a.month).map(d=>`<option value="${d}" ${d===selected?'selected':''}>${fullDate(d)}</option>`).join('');
  const weekday=d=>new Intl.DateTimeFormat('pt-BR',{weekday:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')).replace('.','');
  function pick(value) {selected=value;a.setMonth(value.slice(0,7));}
  function controls(suffix='page'){return `<div class="day-picker"><button data-book-shift="-1" aria-label="Dia anterior">${icon('back')}</button><label class="sr-only" for="book-date-${suffix}">Dia selecionado</label><input id="book-date-${suffix}" type="date" value="${selected}" data-book-day><button data-book-shift="1" aria-label="Próximo dia">${icon('chevron')}</button></div>`}
  function homeDay(){const d=getDay();return `<section class="home-daily"><div><span class="eyebrow">Sua mesa de trabalho</span><h2>O dia em detalhe</h2><p>${weekday(d.date)} · ${fullDate(d.date)} · ${d.transactions.length} movimento(s), ${d.obligations.length} vencimento(s), ${d.tasks.filter(t=>!t.done).length} tarefa(s) abertas</p></div><div class="home-daily-actions">${controls()}${btn('Abrir dia',`data-open="day" data-id="${d.date}"`,'','chevron')}${btn('Ver planilha diária','data-book-go="daily"','','flow')}</div></section>`}
  function monthFigures(id){
    const requested={start:id+'-01',end:monthDays(id).at(-1)},range=fitStatementRange(a.state,a.company,requested,a.account);
    if(!range)return null;
    const p=rangeBook(a.state,a.company,range,'monthly',a.account)[0];
    return {range,partial:range.start!==requested.start||range.end!==requested.end,opening:p.opening,incoming:p.incoming,outgoing:p.outgoing,balance:p.closing,toReceive:p.pendingIn,toPay:p.pendingOut,projected:p.closing+p.pendingIn-p.pendingOut};
  }
  function annual(){return panel('Resumo anual','Uma linha por mês, como na consolidação das planilhas.',`<div class="table-wrap"><table class="annual"><thead><tr><th>Mês</th><th class="money">Entradas realizadas</th><th class="money">Saídas realizadas</th><th class="money">A receber</th><th class="money">A pagar</th><th class="money">Saldo final</th></tr></thead><tbody>${MONTHS.map((m,i)=>{const id=`${a.month.slice(0,4)}-${String(i+1).padStart(2,'0')}`;const f=monthFigures(id);if(!f)return `<tr><td>${m}</td><td colspan="5">Sem extrato carregado</td></tr>`;return `<tr><td><button class="textbtn" data-book-month="${id}">${m}</button>${f.partial?`<small>Até ${fullDate(f.range.end)}</small>`:''}</td><td class="money incoming">${money(f.incoming)}</td><td class="money outgoing">${money(f.outgoing)}</td><td class="money">${money(f.toReceive)}</td><td class="money">${money(f.toPay)}</td><td class="money">${money(f.balance)}</td></tr>`}).join('')}</tbody></table></div>`)}
  function comparison(f){return panel('Previsto × realizado','As obrigações são agrupadas pelo vencimento no mês. Abra para conferir a composição.',`<div class="table-wrap"><table><thead><tr><th>Vencimento</th><th>Obrigação / origem</th><th class="money">Previsto</th><th class="money">Realizado</th><th class="money">Em aberto</th><th>Situação</th></tr></thead><tbody>${f.obs.map(o=>`<tr><td>${date(o.due)}</td><td><button class="textbtn" data-open="obligation" data-id="${o.id}">${esc(o.title)}</button><small>${esc(o.party)} · ${o.kind==='in'?'A receber':'A pagar'}</small></td><td class="money">${money(total(o))}</td><td class="money">${money(a.paid(a.state,o))}</td><td class="money">${money(remaining(a.state,o))}</td><td>${pill(a.status(o).label,a.status(o).tone)}</td></tr>`).join('')}</tbody></table>${!f.obs.length?empty('Sem obrigações no período','Crie uma obrigação a partir de um modelo.'):''}</div>`)}
  function flow(){
    getDay();
    const f=figures(a.state,a.company,a.month,a.account),summary=mode==='daily'?periodSheet.summary():null;
    const monthData=monthFigures(a.month),covered=summary||monthData;const values=!covered?{opening:null,incoming:null,outgoing:null,balance:null,projected:null}:summary?{opening:summary.opening,incoming:summary.incoming,outgoing:summary.outgoing,balance:summary.closing,projected:summary.closing+summary.pendingIn-summary.pendingOut}:monthData;
    return a.titleBlock('Fluxo de caixa','A lógica da sua planilha, do período ao lançamento.',(mode==='daily'?'':`<input type="month" class="monthpick" aria-label="Mês de referência" data-month-select value="${a.month}">`)+btn('Adicionar','data-open="add"','primary','plus'),'Financeiro · livro caixa')+
      `${a.state.dataset?`<p class="statement-coverage">${esc(a.state.dataset.balanceNote||'')} ${a.account==='all'?'Visão conjunta até 31/10; escolha Bradesco para novembro.':monthData?.partial?'Mês parcial, até '+fullDate(monthData.range.end)+'.':''}</p>`:''}<div class="book-totals"><div><span>Saldo inicial ${summary?'do período':'do mês'}</span><strong>${money(values.opening)}</strong></div><div class="income"><span>Entradas realizadas</span><strong>${money(values.incoming)}</strong></div><div class="expense"><span>Saídas realizadas</span><strong>${money(values.outgoing)}</strong></div><div class="closing"><span>Saldo realizado</span><strong>${money(values.balance)}</strong></div><div><span>Projetado com pendências</span><strong>${money(values.projected)}</strong></div></div><div class="toolbar book-toolbar"><div class="segments">${[['daily','Planilha'],['ledger','Lançamentos'],['compare','Previsto × realizado'],['annual','Resumo anual']].map(([key,label])=>`<button data-book-view="${key}" class="${mode===key?'active':''}" aria-pressed="${mode===key}">${label}</button>`).join('')}</div>${mode!=='daily'?`<div class="filters"><select aria-label="Filtrar conta" data-account><option value="all">Todas as contas</option>${a.scope('accounts').map(x=>`<option value="${x.id}" ${a.account===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${mode==='daily'?btn('Exportar grade','data-book-export="1"','','download'):btn('Exportar lançamentos','data-action="export-flow"','','download')}</div>`:''}</div>`+
      (mode==='daily'?periodSheet.render():mode==='ledger'?panel(name(),'Lançamentos em ordem cronológica. Cada linha abre obrigação, comprovante e origem.',a.transactionTable([...f.current].sort(statementOrder),true)):mode==='compare'?comparison(f):annual());
  }
  function dayDetail(id){pick(id);a.render();const d=getDay();return {heading:'Visualização diária',wide:true,body:`<div class="day-detail-head"><div><span class="eyebrow">${esc(a.get('companies',a.company).name)} · ${a.account==='all'?'Todas as contas':esc(a.get('accounts',a.account).name)}</span><h2>${fullDate(d.date)} <small>${weekday(d.date)}</small></h2></div>${controls('dialog')}</div>${!statementCovers(a.state,a.company,d.date,d.date,a.account)?'<p class="statement-coverage">Sem extrato bancário para esta data. As tarefas e obrigações podem ser acompanhadas normalmente.</p>':`<div class="book-totals compact"><div><span>Saldo inicial</span><strong>${money(d.opening)}</strong></div><div class="income"><span>Entradas</span><strong>${money(d.incoming)}</strong></div><div class="expense"><span>Saídas</span><strong>${money(d.outgoing)}</strong></div><div class="closing"><span>Saldo final</span><strong>${money(d.closing)}</strong></div></div>`}<div class="day-detail-grid"><div><div class="drawer-section"><h3>Movimentos realizados <span class="count-badge">${d.transactions.length}</span></h3>${d.transactions.map(t=>link(a.get('obligations',t.obligation)?.title||t.description,t.imported?'transaction':'obligation',t.imported?t.id:t.obligation,`${money(t.amount)} · ${a.get('accounts',t.account)?.name} · ${t.confirmed?'Vínculo confirmado':'Vínculo a conferir'}`,'wallet')).join('')||empty('Nenhum movimento neste dia','O saldo bancário é mantido até o próximo movimento.')}</div><div class="drawer-section"><h3>Obrigações com vencimento no dia <span class="count-badge">${d.obligations.length}</span></h3>${d.obligations.map(o=>link(o.title,'obligation',o.id,`${money(total(o))} · ${a.status(o).label} · em aberto ${money(remaining(a.state,o))}`,'calendar')).join('')||'<p class="annotation">Nenhum vencimento cadastrado para esta data.</p>'}</div></div><div><div class="drawer-section"><h3>Tarefas do dia <span class="count-badge">${d.tasks.length}</span></h3>${d.tasks.map(t=>link(t.title,'task',t.id,`${t.owner} · ${t.done?'Concluída':'A fazer'}`,'task')).join('')||'<p class="annotation">Nenhuma tarefa com prazo nesta data.</p>'}</div><div class="callout">${icon('info')}<span>Vencimento, realização financeira e tarefa têm datas próprias. Os valores bancários só mudam quando existe um movimento.</span></div>${btn('Adicionar neste contexto','data-open="add"','primary','plus')}</div></div>`}}
  function redrawDay(){a.render();if(a.current?.kind==='day'){a.current.id=selected;a.draw()}}
  function click(d){if(periodSheet.click(d))return true;if(d.bookGo){mode=d.bookGo;if(mode==='daily')periodSheet.daily();a.navigate('flow');return true}if(d.bookView){mode=d.bookView;a.render();return true}if(d.bookMonth){a.setMonth(d.bookMonth);selected=d.bookMonth+'-01';mode='daily';periodSheet.daily('month');a.render();return true}if(d.bookShift){const dt=new Date(selected+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+Number(d.bookShift));pick(dt.toISOString().slice(0,10));redrawDay();return true}return false}
  function change(e){if(periodSheet.change(e))return true;if(e.target.hasAttribute('data-book-day')){if(e.target.value){pick(e.target.value);redrawDay()}return true}return false}
  return {flow,homeDay,click,change,openRange(range,account){mode='daily';a.setAccount(account);periodSheet.setRange(range)},selectDate(value){pick(value)},get selectedDate(){return getDay().date},dialog:(kind,id)=>kind==='day'?dayDetail(id):null};
}
